<?php $title='Payments / Sales';require __DIR__.'/includes/header.php';require_admin();$from=$_GET['from']??'';$to=$_GET['to']??'';$q=trim($_GET['q']??'');$where=[];$p=[];if($from){$where[]='DATE(p.paid_at)>=?';$p[]=$from;}if($to){$where[]='DATE(p.paid_at)<=?';$p[]=$to;}if($q){$where[]='(a.ref_number LIKE ? OR p.sender_name LIKE ? OR p.sender_phone LIKE ?)';$like='%'.$q.'%';array_push($p,$like,$like,$like);}$sql='SELECT p.*,a.ref_number FROM payments p JOIN archives a ON a.id=p.archive_id '.($where?'WHERE '.implode(' AND ',$where):'').' ORDER BY p.paid_at DESC';$s=db()->prepare($sql);$s->execute($p);$rows=$s->fetchAll();$total=array_sum(array_map(fn($r)=>(float)$r['amount'],$rows));?><div class="page-head"><div><h1>Payments / Sales</h1><p class="muted">Admin report of all received payments.</p></div></div><form class="search"><input name="q" value="<?=e($q)?>" placeholder="Reference, sender, phone"><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="btn">Filter</button></form><div class="card table-wrap"><table class="table"><thead><tr><th>Date</th><th>Reference</th><th>Sender</th><th>Amount</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('M j, Y g:i A',strtotime($r['paid_at'])))?></td><td><a href="archive_view.php?id=<?=$r['archive_id']?>"><?=e($r['ref_number'])?></a></td><td><?=e($r['sender_name'])?><br><?=e($r['sender_phone'])?></td><td><?=CURRENCY.number_format((float)$r['amount'],2)?></td><td><div class="actions"><a class="btn light" href="payment_receipt.php?id=<?=$r['id']?>">Print payment</a><a class="btn light" href="payment_edit.php?id=<?=$r['id']?>">Edit</a><form method="post" action="payment_delete.php" onsubmit="return confirm('Delete this payment?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Delete</button></form></div></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="empty">No payments found.</td></tr><?php endif;?></tbody><tfoot><tr><th colspan="3">Total</th><th><?=CURRENCY.number_format($total,2)?></th><th></th></tr></tfoot></table></div><?php require __DIR__.'/includes/footer.php';

